        assert_eq!(authorize(140_741_783_355_468, amount, fee), None);
    }

    #[test]
    fn clamps_digits_to_radix_minus_one() {
        assert_eq!(
            authorize(50, 100, 0),
            Some(Authorization { total_debit: 50 })
        );
    }
}
